// Extract readable text from HTML using regex-based cleaning
const html = $input.first().json.data || '';
const articleId = $('Get New Articles').first().json.id;

// Remove script/style tags
let text = html
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[^>]*>[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[^>]*>[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[^>]*>[\s\S]*?<\/header>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const wordCount = text.split(/\s+/).length;
const readingTime = Math.ceil(wordCount / 200);

// Extract og:image
const imageMatch = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i)
  || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
const imageUrl = imageMatch ? imageMatch[1] : null;

return [{ json: { article_id: articleId, content: text.slice(0, 50000), word_count: wordCount, reading_time: readingTime, image_url: imageUrl } }];
